#include "database/migrations.hpp"

// Generated by cmake/EmbedMigrations.cmake from sql/migrations/*.sql.
#include "noteman/migration_scripts.hpp"

namespace noteman::db {

const std::vector<Migration> &migrations() {
    static const std::vector<Migration> kMigrations = [] {
        std::vector<Migration> out;
        for (const auto &m : generated::kMigrationScripts) {
            out.push_back(Migration{m.version, m.name, m.sql});
        }
        return out;
    }();
    return kMigrations;
}

} // namespace noteman::db
